import{_ as c,o,c as d,a3 as i}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Windows","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Windows | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/windows"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/windows"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/windows"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/windows"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/windows"}]]},"headers":[],"relativePath":"zh/xclang/design/windows.md","filePath":"zh/xclang/design/windows.md","lastUpdated":1794509097000}'),l={name:"zh/xclang/design/windows.md"};function a(n,e,t,r,s,g){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h1><p>本页介绍 xclang 的 MinGW 与 MSVC Windows 目标平台、Windows 主机工具链以及 <code>xclang sdk fetch windows</code> 是如何构建和配置的。如何为 Windows 目标平台编译程序见<a href="./../guide/cross-compiling#windows">交叉编译</a>。</p><h2 id="为什么同时提供-mingw-与-msvc" tabindex="-1">为什么同时提供 MinGW 与 MSVC <a class="header-anchor" href="#为什么同时提供-mingw-与-msvc" aria-label="Permalink to &quot;为什么同时提供 MinGW 与 MSVC&quot;">​</a></h2><p>xclang 提供两组 Windows 目标平台，分别面向不同的 ABI：</p><ul><li><strong>MinGW 目标平台</strong>（<code>x86_64-w64-mingw32</code> 与 <code>aarch64-w64-mingw32</code>）：使用 Itanium C++ ABI，搭配基于 UCRT 配置的 MinGW-w64 14.0.0（<code>--with-default-msvcrt=ucrt</code>、<code>--with-default-win32-winnt=0x0A00</code>）。由于 MinGW-w64 的头文件与导入库允许二次分发，它们的 sysroot、<code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code>、<code>winpthreads</code>（<code>libpthread.a</code>）和 <code>compiler-rt</code> 均随每个工具链压缩包内置，开箱即由 <code>ld.lld</code> 静态链接（<a href="./hermeticity">封闭性</a>）。</li><li><strong>MSVC 目标平台</strong>（<code>x86_64-pc-windows-msvc</code> 与 <code>aarch64-pc-windows-msvc</code>）：使用微软 C++ ABI，并通过 <code>lld-link</code> 链接微软的 CRT 与 Windows SDK（可通过运行一次 <code>xclang sdk fetch windows</code> 获取，或在 Windows 上使用本机安装的 Visual Studio）。当链接由 MSVC 编译的库、重度使用 COM 的代码或 Windows 厂商 SDK 时，请使用 MSVC 目标平台。</li></ul><p>Windows 主机工具链（<code>x86_64-w64-mingw32</code> 与 <code>aarch64-w64-mingw32</code>）本身是在 Linux x64 上开启 PGO 与 ThinLTO 交叉编译出的 MinGW 程序（<a href="./pgo">PGO</a>）。</p><h2 id="无需安装-visual-studio-获取-sdk" tabindex="-1">无需安装 Visual Studio 获取 SDK <a class="header-anchor" href="#无需安装-visual-studio-获取-sdk" aria-label="Permalink to &quot;无需安装 Visual Studio 获取 SDK&quot;">​</a></h2><p><code>xclang sdk fetch windows</code> 会根据 <code>xclang/sdk-versions.json</code> 中锁定的版本，从 Visual Studio 频道清单列出的 <code>.vsix</code> 包下载 MSVC CRT 与 STL，并从 NuGet 的 <code>Microsoft.Windows.SDK.CPP</code> 包下载 Windows SDK。Visual Studio 安装程序与 <code>xwin</code> 等工具需要解包 MSI 和 CAB 文件（且 <code>xwin</code> 不提供 macOS 或 Windows on Arm 预编译程序），而 <code>.vsix</code> 与 <code>.nupkg</code> 均为 zip 压缩包，<code>xclang</code> 使用内置代码即可在所有主机上直接解压。</p><p>解压后的目录（<code>&lt;toolchain&gt;/sdk/windows-msvc&lt;ver&gt;-sdk&lt;ver&gt;</code>）采用与 Visual Studio 安装目录一致的 <code>/winsysroot</code> 目录结构：包含 CRT 与 STL 头文件、STL 的 <code>std.ixx</code> 与 <code>std.compat.ixx</code> 模块源码、各架构的静态与 DLL 运行时库、静态运行时库的 <code>.pdb</code> 文件（调试构建链接时会查找这些文件，缺失则会报 <code>LNK4099</code> 警告），以及 Windows SDK 的头文件与导入库（<code>um</code>、<code>ucrt</code>、<code>shared</code>、<code>winrt</code>、<code>cppwinrt</code>；见 <a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。</p><h3 id="配置文件与目标文件指令" tabindex="-1">配置文件与目标文件指令 <a class="header-anchor" href="#配置文件与目标文件指令" aria-label="Permalink to &quot;配置文件与目标文件指令&quot;">​</a></h3><p><code>clang</code> 配置文件不支持条件判断，一旦引用的 <code>@file</code> 不存在就会加载失败。因此 MSVC 目标平台配置文件会固定引入 <code>bin/&lt;triple&gt;-sdk.cfg</code>（以及 <code>&lt;triple&gt;-clang-cl-sdk.cfg</code>）：它在发布压缩包中为空文件，运行 <code>xclang sdk fetch</code>、<code>use</code> 和 <code>remove</code> 时会将其改写为引入 <code>sdk/windows</code> 内对应架构的配置文件（<a href="./toolchain">工具链结构</a>）。</p><p>MSVC 目标平台配置文件还会在每个编译出的目标文件中写入链接器指令：</p><ul><li><code>--dependent-lib=clang_rt.builtins-&lt;arch&gt;.lib</code>：<code>clang</code> 与 <code>clang-cl</code> 在 MSVC 目标平台上都不会自动链接 <code>compiler-rt</code> builtins，缺少它会导致 <code>__int128</code> 除法链接失败。</li><li><code>--linker-option=/nodefaultlib:libucrt.lib</code> 与 <code>--dependent-lib=ucrt.lib</code>：在每个目标文件内声明混合 CRT，即使构建系统直接调用 <code>lld-link</code> 也能生效。由于 <code>lld-link</code> 按顺序读取目标文件中的指令，而目标文件会先指定 <code>ucrt.lib</code>，因此在切换到 <code>/MTd</code> 或静态 UCRT 时，需要在链接命令行上传入 <code>/nodefaultlib:ucrt.lib</code>（<code>/MD</code> 本身使用的就是 <code>ucrt.lib</code>）。</li><li><code>-D_STATIC_INLINE_UCRT_FUNCTIONS=0</code>：除非将 <code>_STATIC_INLINE_UCRT_FUNCTIONS</code> 设为 <code>0</code>（MSVC 19.50 默认将其设为 <code>1</code>），否则 UCRT 会将 <code>ctime</code>、<code>localtime</code> 和 <code>difftime</code> 等函数声明为 <code>static inline</code>。由于 C++ 模块无法导出具有内部链接（internal linkage）的函数，配置文件定义了 <code>_STATIC_INLINE_UCRT_FUNCTIONS=0</code>，使 <code>import std</code> 能够正常编译。</li></ul><p>在 <a href="./../integrations/cmake">CMake</a> 与 <a href="./../integrations/bazel">Bazel</a> 中，xclang 使用 GNU 风格的 <code>clang++</code> 驱动而非 <code>clang-cl</code> 来编译和链接 MSVC 目标平台。通过 <code>clang++</code> 链接每次都会读取目标平台配置文件；而 CMake 配合 <code>clang-cl</code> 时会直接调用不读取配置文件的 <code>lld-link</code>，还会要求调用 <code>mt.exe</code> 处理清单文件（由于 <code>llvm-mt</code> 依赖 <code>libxml2</code>，xclang 未包含 <code>mt.exe</code>）。</p><h2 id="混合-crt" tabindex="-1">混合 CRT <a class="header-anchor" href="#混合-crt" aria-label="Permalink to &quot;混合 CRT&quot;">​</a></h2><p>在 MSVC 目标平台上，二进制文件默认静态链接 <code>libc++</code>（或微软的 STL）以及 VC 运行时库（<code>libvcruntime.lib</code> 与 <code>libcmt.lib</code>），并将 UCRT 动态链接到 Windows 自带的 <code>ucrtbase.dll</code>（<code>api-ms-win-crt-*</code>）。微软将这种组合称为混合 CRT（hybrid CRT）：编译出的程序无需安装 <code>vcruntime140.dll</code> 或 <code>msvcp140.dll</code> 运行库安装包（<a href="./hermeticity">封闭性</a>），同时又能与进程内的所有 DLL 共享同一个堆、<code>errno</code> 和 <code>stdio</code>。选择其他 C 运行时库的参数见<a href="./../guide/cross-compiling#msvc-targets">交叉编译</a>。</p><h2 id="基于-vcruntime-的-libc" tabindex="-1">基于 <code>vcruntime</code> 的 <code>libc++</code> <a class="header-anchor" href="#基于-vcruntime-的-libc" aria-label="Permalink to &quot;基于 `vcruntime` 的 `libc++`&quot;">​</a></h2><p>由于新版 MSVC 工具集可以链接基于旧版构建的库，xclang 使用 <code>clang-cl</code> 基于 <code>windows-2022</code> SDK（MSVC 14.44）为两个 MSVC 架构构建 <code>libc++</code> 与 <code>compiler-rt</code>：</p><ul><li><strong>基于 <code>vcruntime</code> 构建</strong>：<code>libc++</code> 使用微软的 <code>vcruntime</code> 作为 ABI 库，而非 <code>libc++abi</code> 与 <code>libunwind</code>；异常、RTTI 和 <code>operator new</code> 由 <code>vcruntime</code> 负责，C 标准库则由 UCRT 提供。<a href="./../reference/patches">补丁 0016</a> 为 <code>libc++</code> 提供了不依赖微软 STL 库的独立 <code>std::set_new_handler</code> 实现，并去掉了重复的 <code>std::nothrow</code> 定义。</li><li><strong>一个库文件通用于所有 CRT</strong>：<code>libc++</code> 使用 <code>/MT /Zl</code> 编译，不嵌入默认 C 运行时指令，其对 UCRT 与 <code>vcruntime</code> 的调用既可解析到静态库，也可解析到 DLL 导入库。同时它使用 <code>_CRT_STDIO_ARBITRARY_WIDE_SPECIFIERS</code> 而非 <code>_CRT_STDIO_ISO_WIDE_SPECIFIERS</code> 构建，避免与使用微软默认宽字符 <code>printf</code> 格式说明符的目标文件一起链接时触发 <code>/failifmismatch</code> 错误。因此，同一个 <code>lib/clang/&lt;major&gt;/lib/windows/libc++-&lt;arch&gt;.lib</code> 可直接与混合 CRT、<code>/MT</code>、<code>/MD</code> 以及调试版 CRT 链接。</li><li><strong>通过 <code>#pragma comment(lib, ...)</code> 自动链接</strong>：<code>libc++-&lt;arch&gt;.lib</code> 与 <code>compiler-rt</code> 一起存放在 <code>lld-link</code> 会自动搜索的 <code>lib/clang/&lt;major&gt;/lib/windows/</code> 目录下，目标平台的 <code>__config_site</code> 则通过 <code>#pragma comment(lib, ...)</code> 声明引用它。任何包含 <code>libc++</code> 头文件的翻译单元都会自动链接 <code>libc++-&lt;arch&gt;.lib</code>（即使 CMake 或 MSBuild 直接调用 <code>lld-link</code> 也不例外），而 C 目标文件与启用 <code>-stdlib=platform</code> 的目标文件则不会链接它。</li><li><strong><code>-stdlib++-isystem</code> 与 <code>import std</code></strong>：<code>clang</code> 的 MSVC 工具链会忽略 <code>-stdlib=</code>，因此默认配置文件通过 <code>-stdlib++-isystem</code>（在 <code>clang-cl</code> 中为 <code>/clang:-stdlib++-isystem</code>，由<a href="./../reference/patches">补丁 0011</a> 消除编译 C 代码时的未使用告警）提供 <code>libc++</code> 头文件。传入 <code>-stdlib=platform</code> 会切换到不含 <code>-stdlib++-isystem</code> 的 <code>&lt;triple&gt;-system.cfg</code>（<a href="./../reference/patches">补丁 0018</a>），让 <code>clang</code> 查找 SDK 中的 STL 头文件。在使用 <code>import std</code> 时，由于 <code>clang -print-library-module-manifest-path</code> 只查找 <code>libc++.a</code>，CMake 包会直接从 <code>&lt;target&gt;/lib/libc++.modules.json</code> 与 <code>&lt;target&gt;/share/libc++/v1</code> 读取 <code>libc++</code> 的模块清单；启用 <code>-stdlib=platform</code> 时则会编译 STL 的 <code>std.ixx</code> 与 <code>std.compat.ixx</code>（在 <code>arm64</code> 上会先于模块包含 <code>&lt;malloc.h&gt;</code>，防止 <code>_alloca</code> 重复声明）。</li></ul><h2 id="启动器-launcher" tabindex="-1">启动器（Launcher） <a class="header-anchor" href="#启动器-launcher" aria-label="Permalink to &quot;启动器（Launcher）&quot;">​</a></h2><p>在 Windows 上创建符号链接需要开启开发者模式或拥有管理员权限，且 Windows 的 conda 软件包不支持符号链接，因此 Windows 工具链压缩包不包含任何符号链接。取而代之的是，<code>bin/</code> 下的每个工具可执行文件（<code>clang.exe</code>、<code>clang++.exe</code>、<code>ld.lld.exe</code> 等）都是由 <a href="https://github.com/clice-io/xclang/blob/main/toolchain/launcher/alias.c" target="_blank" rel="noreferrer"><code>toolchain/launcher/alias.c</code></a> 编译而成的轻量启动器，负责启动 <code>llvm.exe &lt;name&gt; &lt;arguments&gt;</code>：</p><ul><li><strong>子命令名称</strong>：多合一程序 <code>llvm</code> 根据调用名选择具体工具，而在 Windows 上 LLVM 会在检查 <code>argv[0]</code> 之前将其替换为自身模块的文件名（<code>llvm.exe</code>）。把 <code>&lt;name&gt;</code> 作为第一个参数传入即可保留原本的工具名称（区分 <code>clang++</code> 与 <code>clang</code>、<code>ld.lld</code> 与通用 <code>lld</code>）。</li><li><strong>关闭即终止的作业对象（job object）</strong>：启动器通过 <code>PROC_THREAD_ATTRIBUTE_JOB_LIST</code> 直接在配置了「关闭即终止」的 Windows 作业对象内创建 <code>llvm.exe</code> 进程。当构建系统超时或杀死启动器时，编译器进程会随之一起终止，不会残留占用文件句柄或工作目录的后台进程。</li><li><strong>进程创建开销</strong>：每次编译会启动两个进程而非一个。这一开销在几毫秒即可编译完的极小 C 文件上较为明显，但在 C++ 翻译单元上可以忽略不计（<a href="./pgo">PGO</a>）。希望省去额外进程启动开销的构建工具可以直接调用 <code>llvm.exe clang++ ...</code>。</li></ul><h2 id="gc-sections-与静态初始化器" tabindex="-1"><code>gc-sections</code> 与静态初始化器 <a class="header-anchor" href="#gc-sections-与静态初始化器" aria-label="Permalink to &quot;`gc-sections` 与静态初始化器&quot;">​</a></h2><p>在 MinGW 目标平台上，<code>ld.lld --gc-sections</code> 会丢弃没有任何符号引用的 COMDAT 节，包括用于注册内联或模板测试用例的静态初始化器（static initializer）。在 ELF 目标平台上，<code>.init_array</code> 会作为垃圾回收的根节点保留这些初始化器；而在 MinGW 上，<code>[[gnu::used]]</code> 不会生成链接器的 <code>/include</code> 指令。在 clice 中，为 MinGW 开启 <code>--gc-sections</code> 曾导致两个测试套件未被注册，Windows 单元测试数量在无报错的情况下从 1,619 降到了 1,551；而关闭它则会使剥离符号后的测试程序体积从 64 MB 增加到 82 MB。</p><p>因此，Bazel 模块在优化构建中仅对 Linux 目标平台默认启用 <code>gc_sections</code>，对 Windows 目标平台则保持关闭（若目标不依赖未引用的 COMDAT 初始化器，可通过 <code>--features=gc_sections</code> 手动开启）。</p><h2 id="头文件大小写敏感问题" tabindex="-1">头文件大小写敏感问题 <a class="header-anchor" href="#头文件大小写敏感问题" aria-label="Permalink to &quot;头文件大小写敏感问题&quot;">​</a></h2><p>Windows 文件系统不区分大小写，因此 Windows 代码常写成 <code>#include &lt;Windows.h&gt;</code>、<code>&lt;BaseTsd.h&gt;</code> 或 <code>&lt;WinSock2.h&gt;</code>，而 MinGW-w64 的头文件名均为全小写（<code>windows.h</code>、<code>basetsd.h</code>、<code>winsock2.h</code>）。xclang 未在 MinGW sysroot 中添加混合大小写的链接；在区分大小写的 Linux 文件系统上，MinGW 代码必须使用全小写头文件名。</p><p>微软自身的 CRT、STL 和 Windows SDK 头文件及导入库在内部混用了不同大小写拼写。当 <code>xclang sdk fetch windows</code> 在区分大小写的文件系统上解压 Windows SDK 时，会自动创建约 3,600 个链接（包括 <code>windows.h</code>、指向 <code>WinBase.h</code> 的 <code>winbase.h</code>、指向 <code>LIBCMT.lib</code> 的 <code>libcmt.lib</code>、<code>BaseTsd.h</code>、<code>Mstcpip.h</code>、<code>Kernel32.lib</code>、<code>Iphlpapi.lib</code> 等），因此现有的 Windows 代码无需修改即可直接编译。</p><h2 id="visual-studio-与-compiler-rt" tabindex="-1">Visual Studio 与 <code>compiler-rt</code> <a class="header-anchor" href="#visual-studio-与-compiler-rt" aria-label="Permalink to &quot;Visual Studio 与 `compiler-rt`&quot;">​</a></h2><ul><li><strong>在 MinGW 编译的 <code>clang</code> 中查找 Visual Studio</strong>：上游 LLVM 仅在使用 MSVC 编译时才会构建 Visual Studio Setup API 查找逻辑，导致 MinGW 编译出的 <code>clang</code> 回退到仅适用于 Visual Studio 2010 及更早版本的注册表项查找。<a href="./../reference/patches">补丁 0004</a>（<code>llvm/llvm-project#226794</code>）在 MinGW 下启用了 Setup API 查找，使 <code>clang</code> 以及 clice 等基于 <code>libclang</code> 的工具能够在 Windows 主机上找到 Visual Studio 2017 及更高版本。</li><li><strong>优先使用 xclang 的 <code>compiler-rt</code></strong>：在未下载 SDK 的 Windows 主机上，上游 <code>clang</code> 会把 Visual Studio 的库目录排在 xclang 的 <code>compiler-rt</code> 目录之前传给 <code>lld-link</code>，导致 Visual Studio 自带的 <code>clang_rt.*.lib</code> 遮蔽了 xclang 的版本，在 Visual Studio 18（MSVC 14.51）上破坏了 <code>__int128</code> 除法、UBSan 和 libFuzzer。<a href="./../reference/patches">补丁 0012</a> 将 xclang 的 <code>compiler-rt</code> 目录排在最前面。</li></ul><h2 id="每次链接产出逐字节相同的结果" tabindex="-1">每次链接产出逐字节相同的结果 <a class="header-anchor" href="#每次链接产出逐字节相同的结果" aria-label="Permalink to &quot;每次链接产出逐字节相同的结果&quot;">​</a></h2><p>xclang 省略了 PE/COFF 时间戳（<a href="./../reference/patches">补丁 0014</a>），使重复编译和链接能够生成一致的二进制文件。在大型 PGO 与 ThinLTO 链接（例如 clice 600 MB 的 <code>clice.exe</code>）中，<code>lld-link</code> 过去按函数名索引调用图 profile 排序，导致不同目标文件里的同名 <code>static</code> 函数会根据哈希表内存地址互相覆盖 profile 权重；<a href="./../reference/patches">补丁 0017</a> 改为保留首个条目，保证每次链接产出的结果逐字节相同。</p><h2 id="asan-的-dll" tabindex="-1">ASan 的 DLL <a class="header-anchor" href="#asan-的-dll" aria-label="Permalink to &quot;ASan 的 DLL&quot;">​</a></h2><p>在 Windows 上，无论是 MinGW 还是 MSVC 目标平台，<code>compiler-rt</code> 都只构建动态链接的 AddressSanitizer 运行时库：<code>libclang_rt.asan_dynamic.dll</code> 与 <code>clang_rt.asan_dynamic-x86_64.dll</code>。作为仅供测试使用的<a href="./hermeticity">封闭性</a>例外，每个带 ASan 插桩的二进制文件在启动时都会从自身所在目录或 <code>PATH</code> 中加载这个 DLL（<a href="./../features/sanitizers">sanitizer</a>）：</p><ul><li><strong>MinGW 的 ASan DLL 静态链接 <code>libc++</code> 与 <code>libunwind</code></strong>：不同于 <code>llvm-mingw</code> 需要加载 <code>libc++.dll</code> 的 ASan DLL，xclang 的 MinGW DLL 仅依赖 Windows 系统 DLL 与 UCRT，而程序自身则会链接经 ASan 插桩的 <code>libc++</code>。MSVC 的 ASan DLL（<code>clang_rt.asan_dynamic-x86_64.dll</code>）则由 <code>compiler-rt</code> 链接到动态 VC 运行时库（<code>vcruntime140.dll</code>）。</li><li><strong>内置于 <code>x86_64</code> Windows 主机的 <code>bin/</code> 目录</strong>：<code>x86_64</code> Windows 工具链压缩包在 <code>bin/</code> 下同时存放了 MinGW 与 MSVC 的 ASan DLL 副本，只要工具链在 <code>PATH</code> 中，ASan 程序就能直接找到运行时库。将 ASan 程序拷贝到其他机器时，请把对应的 DLL 一并放在它旁边。</li><li><strong>在 Bazel 中自动拷贝到二进制文件旁</strong>：启用 <code>--features=asan</code> 的 Bazel 构建会从 <code>@bazel_tools//tools/cpp:cc_runtimes_toolchain_type</code> 获取这个 DLL，并由 <code>copy_dynamic_libraries_to_binary</code> 特性将其拷贝到 <code>bazel-bin</code> 下的可执行文件旁以及供 <code>bazel run</code> 和 <code>bazel test</code> 使用的 runfiles 目录中。</li><li><strong>不支持在 Windows on Arm 的 <code>x86_64</code> 模拟器下运行</strong>：<code>x86_64</code> ASan 程序在 <code>arm64</code> Windows 的 <code>x86_64</code> 模拟环境下运行时无法拦截 UCRT 函数。</li></ul>',35)])])}const m=c(l,[["render",a]]);export{u as __pageData,m as default};
